"""
Devocional Completo - Sistema de devocionais diários baseado na fé reformada
365 devocionais com passagens, reflexões e orações
"""
from datetime import date, timedelta
import hashlib

DEVOCIONAIS = {
    'janeiro': [
        {'dia': 1, 'titulo': 'O Princípio de Todas as Coisas', 'passagem': 'Gênesis 1:1-3', 'texto': 'No princípio criou Deus os céus e a terra. A terra era sem forma e vazia, e havia trevas sobre a face do abismo. E o Espírito de Deus se movia sobre a face das águas.', 'reflexao': 'Deus é o soberano criador de todas as coisas. No caos original, Sua voz trouxe ordem e vida. Assim como Ele criou o universo com Sua palavra, Ele pode renovar sua vida hoje. A primeira palavra da Bíblia é "no princípio" - Deus sempre começa primeiro.', 'oracao': 'Senhor, Criador de todas as coisas, obrigado por Teu poder que transforma o caos em ordem. Ajuda-me a começar este ano reconhecendo Tua soberania sobre toda a minha vida. Em nome de Jesus, amém.', 'cor': '#00d4ff'},
        {'dia': 2, 'titulo': 'A Queda e a Promessa Redentora', 'passagem': 'Gênesis 3:1-15', 'texto': 'A serpente enganou Eva, que comeu da fruta e deu a Adão. Ambos abriram os olhos para a própria nudez. Mas Deus prometeu: "A semente da mulher esmagará a cabeça da serpente."', 'reflexao': 'O pecado entrou no mundo pela desobediência, mas desde o princípio Deus já tinha um plano de redenção. A "semente da mulher" é uma profecia sobre Jesus Cristo, que viria para vencer o mal. Mesmo no julgamento, há promessa de salvação.', 'oracao': 'Deus de misericórdia, reconheço que o pecado corrompeu minha natureza. Obrigado pela promessa de um Redentor que veio para nos restaurar. Que eu viva grato pela Tua graça que antecedeu minha própria necessidade. Amém.', 'cor': '#ff0080'},
        {'dia': 3, 'titulo': 'A Fé de Abraão', 'passagem': 'Gênesis 12:1-4; 15:6', 'texto': 'Deus disse a Abraão: "Vai-te da tua terra." Abraão obedeceu e partiu, sem saber para onde ia. E creu no Senhor, que lhe imputou isso como justiça.', 'reflexao': 'A fé de Abraão é modelo para todos os crentes. Ele não viu o cumprimento das promessas, mas creu na fidelidade de Deus. "Imputar justiça" significa que Deus creditou a Abraão a justiça que não era própria, mas que vem pela fé. Isso é o evangelho em Gênesis.', 'oracao': 'Pai de Abraão, fortalece minha fé para obedecer-Te mesmo quando não vejo o caminho. Ensina-me a confiar na Tua Palavra como Abraão confiou. Que eu creia nas Tuas promessas acima das minhas circunstâncias. Amém.', 'cor': '#ffd700'},
        {'dia': 4, 'titulo': 'Deus Provê o Seu Povo', 'passagem': 'Êxodo 16:4-35', 'texto': 'Deus mandou maná do céu para alimentar Israel no deserto. "Eis que vos farei chover pão do céu." O povo devia recolher a porção diária, confiando na providência divina.', 'reflexao': 'O maná é tipo de Cristo, o pão da vida (Jo 6:35). Assim como Israel recebia maná diariamente, nós precisamos da Palavra de Deus e da comunhão com Cristo todos os dias. A provisão divina é suficiente e pontual.', 'oracao': 'Deus providente, obrigado por cuidar de mim dia a dia. Assim como deu maná a Israel, dá-me o pão da vida que é Cristo Jesus. Ensina-me a confiar na Tua provisão e não preocupar-me com o amanhã. Amém.', 'cor': '#00ff88'},
        {'dia': 5, 'titulo': 'A Aliança no Sinai', 'passagem': 'Êxodo 19:5-8; 20:1-3', 'texto': 'No monte Sinai, Deus estabeleceu aliança com Israel: "Se vós ouvirdes a Minha voz e guardardes a Minha aliança, sereis Meu povo peculiar." Então deu os Dez Mandamentos.', 'reflexao': 'A aliança sinaítica revela a santidade de Deus e a responsabilidade do povo. Deus chamou Israel para ser santo, separado para Ele. Os Dez Mandamentos não são fardos pesados, mas caminhos de vida dados por amor.', 'oracao': 'Senhor santo, perdoa quando desobedeço às Tuas instruções. Obrigado por revelar Tua vontade nos mandamentos. Dá-me o desejo de obedecer não por medo, mas por amor. Que eu busque Tua santidade todos os dias. Amém.', 'cor': '#a855f7'},
        {'dia': 6, 'titulo': 'O Cordeiro Pascal', 'passagem': 'Êxodo 12:1-14; 1 Coríntios 5:7', 'texto': 'Israel devia sacrificar um cordeiro sem mancha e passar o sangue nos batentes. "Quando eu vir o sangue, passarei por vós." Paulo diz: "Cristo, nosso cordeiro pascal, foi sacrificado."', 'reflexao': 'O cordeiro pascal é a sombra mais clara de Cristo no Antigo Testamento. Jesus é o Cordeiro de Deus que tira o pecado do mundo (Jo 1:29). O sangue nos batentes protegeu Israel da morte; o sangue de Cristo nos protege da morte eterna.', 'oracao': 'Cordeiro de Deus, obrigado pelo Teu sacrifício na cruz. O Teu sangue me protege da morte eterna. Que eu nunca esqueça que minha salvação se baseia no Teu sacrifício perfeito, não nas minhas obras. Amém.', 'cor': '#ff6b35'},
        {'dia': 7, 'titulo': 'A Pedra Golpeada e a Água da Vida', 'passagem': 'Números 20:7-13; 1 Coríntios 10:4', 'texto': 'Moisés golpeou a rocha no deserto, e dela saiu água para o povo beber. Paulo diz: "A pedra era Cristo." Mesmo assim, Moisés foi desobediente e não entrou na terra prometida.', 'reflexao': 'Cristo é a rocha que nos dá água viva da salvação. Assim como da rocha golpeada brotou água para o povo, Cristo, a Rocha espiritual, foi ferido (crucificado) uma única vez por nossos pecados. A água que brota é o Espírito Santo que satisfaz nossa sede espiritual.', 'oracao': 'Rocha viva, Cristo Jesus, brota em mim a água da vida. Obrigado por ser minha suficiência no deserto da vida. Que eu nunca tente encontrar satisfação em fontes secas, mas beba de Ti, a única fonte viva. Amém.', 'cor': '#00d4ff'},
        {'dia': 8, 'titulo': 'Deus Nunca Falha', 'passagem': 'Números 23:19; Lamentações 3:22-23', 'texto': 'Deus não é homem para que minta, nem filho de homem para que se arrependa. As misericórdias do Senhor se renovam a cada manhã; grandes são as Tuas fidelidades.', 'reflexao': 'A imutabilidade de Deus é um pilar da teologia reformada. Ele não muda de ideia, não Se arrepende, não falha. Suas promessas são seguras como Ele próprio. Cada manhã é uma nova oportunidade de experimentar Tua graça renovada.', 'oracao': 'Deus imutável, obrigado por ser sempre o mesmo. Não muda, não falha, não desiste de mim. Quando o mundo oscila, Tu permaneces. Ensina-me a descansar na Tua fidelidade que nunca se esgota. Amém.', 'cor': '#ffd700'},
        {'dia': 9, 'titulo': 'Amor que Restaura - Oseias', 'passagem': 'Oseias 2:14-23', 'texto': 'Deus diz: "Atrairei-a e a levarei ao deserto e lhe falarei ao coração." Promete restaurar a sua vinha e dar-lhe o vale de Acor como porta de esperança.', 'reflexao': 'O livro de Oseias revela o amor incondicional de Deus por um povo infiel. Mesmo quando Israel trocou a adoração verdadeira pelos ídolos, Deus não desistiu. Ele busca Sua esposa com amor persistente, como Cristo busca a igreja.', 'oracao': 'Deus de amor, quando Te esqueço e busco substitutos para Tua adoração, atrai-me de volta ao deserto onde possas falar com meu coração. Restaura-me, pois Tu és o esposo da minha alma. Amém.', 'cor': '#ff0080'},
        {'dia': 10, 'titulo': 'O Juíz é o Salvador', 'passagem': 'Juízes 2:16-19', 'texto': 'O Senhor suscitava juízes que livravam Israel. Mas quando o juiz morria, o povo voltava a pecar, pior que antes. O ciclo de pecado e livramento se repetia.', 'reflexao': 'O livro de Juízes demonstra a incapacidade humana de se auto-salvar. Cada juiz era uma solução temporária. O povo precisava de um Salvador perfeito e eterno - Jesus Cristo, o Juiz justo que também é o Redentor.', 'oracao': 'Senhor, reconheço que não posso me livrar do pecado por minhas próprias forças. Preciso de Ti como Salvador. Quebranta meu orgulho que diz "consigo sozinho" e me faça dependente exclusivamente de Ti. Amém.', 'cor': '#ff6b35'},
        {'dia': 11, 'titulo': 'A Mulher de Fé - Rute', 'passagem': 'Rute 1:16-17', 'texto': 'Rute disse a Noemi: "Para onde fores, irei; onde pousares, pousarei. Teu povo é meu povo, e teu Deus é meu Deus." A moabita tornou-se antepassada de Davi.', 'reflexao': 'Rute, uma moabita, demonstrou lealdade e fé que muitos israelitas não tiveram. Ela deixou sua terra e seus deuses para seguir o Deus verdadeiro. Sua história nos mostra que a salvação é para todos os povos, e que Deus usa os humildes para cumprir Seus propósitos.', 'oracao': 'Deus de todas as nações, obrigado por me incluir no Teu povo mesmo sendo indigno. Como Rute, escolho seguir-Te aonde quer que Vás. Que eu seja leal à Tua Palavra e à Tua igreja todos os dias. Amém.', 'cor': '#00ff88'},
        {'dia': 12, 'titulo': 'O Rei que Humildemente Buscou a Deus', 'passagem': '1 Crônicas 29:10-20', 'texto': 'Davi orou: "Tu és o Senhor, a ti pertence a grandeza, o poder, a glória, o triunfo e a honra, porque tudo o que há nos céus e na terra é teu."', 'reflexao': 'Davi, apesar de seus pecados, era um homem segundo o coração de Deus porque reconhecia a soberania divina em tudo. Ele entregou o reino a Salomão com humildade, reconhecendo que todos os bens vêm de Deus. A verdadeira riqueza é reconhecer a nossa pobreza espiritual.', 'oracao': 'Soberano de tudo, inclino-me diante de Tua majestade. Tu tens o poder e a glória; eu tenho necessidade. Recebe minha vida humilde e usa-a para Teu propósito. Que eu nunca esqueça que tudo vem de Ti. Amém.', 'cor': '#a855f7'},
        {'dia': 13, 'titulo': 'Sabedoria Mais Preciosa', 'passagem': 'Provérbios 2:1-11', 'texto': 'Inclina o teu ouvido à sabedoria, aplica o teu coração ao entendimento. Pois o Senhor dá sabedoria; dá de boa vontade a sapiência e o conhecimento.', 'reflexao': 'A sabedoria bíblica não é conhecimento intelectual, mas o temor do Senhor. Buscar sabedoria é um ato de fé e humildade. Deus promete dar sabedoria generosamente a quem a pede com sinceridade (Tg 1:5).', 'oracao': 'Deus sábio, dá-me sabedoria para tomar decisões que Te honrem. Mais do que riquezas ou fama, quero conhecer Tuas veredas. Que Tua Palavra seja lâmpada para os meus passos e luz para o meu caminho. Amém.', 'cor': '#ffd700'},
        {'dia': 14, 'titulo': 'O Eclesiastes e a Vaidade da Vida', 'passagem': 'Eclesiastes 1:2; 12:13', 'texto': '"Vaidade de vaidades, diz o Eclesiastes, vaidade de vaidades, tudo é vaidade." Mas a conclusão: "Teme a Deus e guarda os Seus mandamentos."', 'reflexao': 'Salomão experimentou tudo que o mundo oferece e concluiu que tudo é "vaidade" - vapor, sem substância eterna. Só o temor do Senhor tem valor permanente. O mundo oferece prazeres momentâneos, mas só Deus satisfaz a alma eterna.', 'oracao': 'Deus eterno, quando busco satisfação em bens materiais ou prazeres momentâneos, lembra-me que só Tu és suficiente. Que eu não desperdice minha vida em vaidades, mas invista no que tem valor eterno. Amém.', 'cor': '#00d4ff'},
        {'dia': 15, 'titulo': 'O Amor de Noivos - Cântico dos Cânticos', 'passagem': 'Cântico 2:10-14; 8:6-7', 'texto': '"Levanta-te, meu amor, minha formosa, e vem. O amor é forte como a morte; as suas afeições são incêndios divinos, um fogo celeste."', 'reflexao': 'O Cântico dos Cânticos celebra o amor entre noivos como reflexo do amor entre Cristo e a igreja (Ef 5:25-32). O amor não é fraqueza - é força que resiste à morte. Assim Cristo nos ama, com amor que nenhum dilúvio pode apagar.', 'oracao': 'Deus de amor, ensina-me a amar como Tu amas - com fidelidade, força e entrega. Que eu honre o sagrado pacto do matrimônio e reflita em minha vida o amor de Cristo pela igreja. Amém.', 'cor': '#ff0080'},
        {'dia': 16, 'titulo': 'Profeta de Obediência', 'passagem': 'Jonas 1:1-4; 4:1-11', 'texto': 'Jonas fugiu da chamada de Deus, foi engolido por um grande peixe, e depois obedeceu. Mesmo assim, ficou irado quando Deus perdoou Nínive.', 'reflexao': 'Jonas revela nossa tendência de querer julgar outros enquanto recebemos graça. Deus é misericordioso para com todos os povos, mesmo nossos inimigos. A missão de Deus transcende nossas preferências e preconceitos.', 'oracao': 'Deus de misericórdia universal, perdoa quando quero limitar Tua graça só para quem eu considero digno. Ensina-me a alegrar-me quando os outros recebem Teu amor, mesmo quando me incomodam. Amém.', 'cor': '#00ff88'},
        {'dia': 17, 'titulo': 'Daniel na Cova dos Leões', 'passagem': 'Daniel 6:1-28', 'texto': 'Daniel continuou orando a Deus mesmo sob ameaça de morte. Foi lançado na cova dos leões, mas Deus mandou um anjo para fechar as bocas dos animais.', 'reflexao': 'A fidelidade de Daniel nos ensina que a obediência a Deus é mais importante que a segurança pessoal. Daniel não negociou sua fé. Deus honrou sua fidelidade de forma sobrenatural. Onde Deus é fiel, o perigo não tem a última palavra.', 'oracao': 'Senhor de Daniel, dá-me coragem para ser fiel mesmo quando custa. Que eu não negue Tua Palavra por medo. Confiarei em Ti mesmo na cova dos leões, pois Tu controlas até mesmo os animais selvagens. Amém.', 'cor': '#ff6b35'},
        {'dia': 18, 'titulo': 'O Servo Sofredor', 'passagem': 'Isaías 52:13-53:12', 'texto': '"Eis que o Meu servo prosperará; será exaltado e muito sublimado. Porque as nossas doenças Ele carregou, e as nossas dores Ele tomou sobre Si."', 'reflexao': 'Isaías 53 é a profecia mais clara sobre a crucificação de Jesus, escrita 700 anos antes do evento. O Servo Sofredor toma sobre Si os pecados do povo, sendo ferido pelas nossas transgressões. Ele foi morto pelos pecados alheios, mas ressuscitou para justificar muitos.', 'oracao': 'Servo Sofredor, Jesus Cristo, obrigado pelas Tuas feridas que me sararam. Tu carregaste meus pecados na cruz. Que eu nunca minimize o Teu sacrifício e viva grato pela Tua graça que me salvou do inferno merecido. Amém.', 'cor': '#a855f7'},
        {'dia': 19, 'titulo': 'Deus Conosco - Emmanuel', 'passagem': 'Isaías 7:14; Mateus 1:22-23', 'texto': '"A virgem conceberá e dará à luz um filho, e chamarás o Seu nome Emanuel, que traduzido é: Deus conosco."', 'reflexao': 'A maior notícia da história é que Deus veio habitar entre nós. Emmanuel - Deus conosco. Não um deus distante e indiferente, mas um Salvador próximo que experimentou nossas dores e tentações, sem pecado.', 'oracao': 'Emmanuel, obrigado por não ficares no céu, mas desceres à terra para nos salvar. Que eu nunca sinta que estou sozinho, pois Tu és Deus conosco, todos os dias, até a consumação dos séculos. Amém.', 'cor': '#00d4ff'},
        {'dia': 20, 'titulo': 'A Estrela de Jacó', 'passagem': 'Números 24:17; Mateus 2:1-12', 'texto': 'Balaão profetizou: "Surgirá uma estrela de Jacó." Magos do oriente seguiram uma estrela para encontrar o rei dos judeus e lhe trouxeram ouro, incenso e mirra.', 'reflexao': 'A estrela de Jacó apontava para o Messias. Os magos, pagãos de longe, reconheceram o rei que os judeus muitas vezes rejeitaram. Jesus veio para todos os povos - judeus e gentios, ricos e pobres, sábios e ignorantes.', 'oracao': 'Rei dos judeus, estrela que guia os perdidos, guia-me sempre para Ti. Que eu nunca perca de vista Teu guia, mesmo quando o caminho pareça escuro. Tu és a luz do mundo. Amém.', 'cor': '#ffd700'},
        {'dia': 21, 'titulo': 'O Batismo de Jesus', 'passagem': 'Mateus 3:13-17', 'texto': 'Jesus foi batizado por João no Jordão. Ao subir da água, os céus se abriram e o Espírito desceu como pomba, e uma voz do céu disse: "Este é o Meu Filho amado, em quem Me comprazo."', 'reflexao': 'No batismo, a Trindade se manifesta: Pai fala, Filho é batizado, Espírito desce. Jesus não precisava de arrependimento, mas Se identificou com os pecadores. O batismo cristão é sinal da aliança e identificação com Cristo.', 'oracao': 'Pai que falou do céu, Filho que Se humilhou, Espírito que desceu sobre as águas - Trindade santa, obrigado pelo privilégio de fazer parte da Tua família pelo batismo. Que eu viva digno desta aliança. Amém.', 'cor': '#00ff88'},
        {'dia': 22, 'titulo': 'A Tentação no Deserto', 'passagem': 'Mateus 4:1-11', 'texto': 'Jesus foi levado ao deserto para ser tentado pelo diabo. Três tentações: transformar pedras em pão, lançar-Se do templo, adorar Satanás. Jesus resistiu com a Palavra de Deus.', 'reflexao': 'Jesus venceu onde Adão falhou. Enquanto Adão caiu no jardim abundante, Jesus venceu no deserto de fome. A arma de Jesus era "esta escrito" - a Palavra de Deus. Assim também nós devemos resistir ao diabo com a Escritura.', 'oracao': 'Filho de Deus, fortalece-me para resistir às tentações como Tu resististe. Que eu tenha Tua Palavra escondida no coração para vencer o mal. Quando o tentador vier, dá-me coragem para dizer: "Está escrito." Amém.', 'cor': '#ff0080'},
        {'dia': 23, 'titulo': 'O Sermão da Montanha', 'passagem': 'Mateus 5:1-12', 'texto': '"Bem-aventurados os pobres de espírito, porque deles é o reino dos céus. Bem-aventurados os que choram, porque eles serão consolados."', 'reflexao': 'O Sermão da Montanha inverte os valores do mundo: os pobres são abençoados, os humildes herdam a terra, os pacificadores são chamados filhos de Deus. A felicidade bíblica (bem-aventurança) não depende de circunstâncias, mas de relação com Deus.', 'oracao': 'Mestre de todos os tempos, ensina-me a viver as bem-aventuranças que contradizem o mundo. Que eu seja pobre de espírito, humilde, misericordioso e pacificador, mesmo quando o mundo ri de mim. Amém.', 'cor': '#a855f7'},
        {'dia': 24, 'titulo': 'O Poder da Parábola', 'passagem': 'Mateus 13:1-23', 'texto': 'Jesus ensinou em parábolas: o Semeador, o Joio e o Trigo, o Grão de Mostarda. Cada parábola revelava verdades espirituais de forma simples e profunda.', 'reflexao': 'As parábolas de Jesus são joias de sabedoria. Elas revelam o reino de Deus de forma que os humildes entendem, mas os orgulhosos perdem. A parábola do semeador nos mostra que a Palavra cai em diferentes tipos de solo - nosso coração determina o fruto.', 'oracao': 'Semeador divino, prepara o solo do meu coração para receber a Tua semente. Remove os espinhos da distração, as pedras da dureza, e a superficialidade que impede o fruto. Que eu ouça e produza fruto de justiça. Amém.', 'cor': '#ffd700'},
        {'dia': 25, 'titulo': 'Cristo na Tempestade', 'passagem': 'Mateus 8:23-27', 'texto': 'Jesus dormia no barco quando uma grande tempestade surgiu. Os discípulos gritaram: "Salva-nos, Senhor, porque estamos perecendo!" Jesus levantou-se, repreendeu os ventos e o mar, e fez-se silêncio.', 'reflexao': 'Na tempestade da vida, Jesus está conosco mesmo quando parece dormir. Os discípulos tiveram fé para gritar por ajuda, mas precisavam de mais fé para confiar no sono de Jesus. Ele tem autoridade sobre toda a criação.', 'oracao': 'Senhor das tempestades, perdoa minha falta de fé quando as ondas da vida ameaçam afogar-me. Tu dormes porque controlas tudo. Dá-me paz mesmo quando o mar se agita, pois Tu és o mesmo que calma os ventos e as ondas. Amém.', 'cor': '#00d4ff'},
        {'dia': 26, 'titulo': 'A Rainha do Sul e Norte', 'passagem': 'Mateus 12:42; Lucas 11:31', 'texto': '"Eis aqui está uma maior que Salomão." A rainha do sul veio dos confins da terra para ouvir a sabedoria de Salomão, e eis que há aqui uma maior que Salomão."', 'reflexao': 'Jesus se identifica como maior que Salomão, o homem mais sábio da terra. Se a sabedoria humana de Salomão atraiu uma rainha de longe, quanto mais a sabedoria divina de Cristo deve atrair nossos corações? Jesus é a sabedoria de Deus encarnada.', 'oracao': 'Sabedoria de Deus encarnada, perdoa quando busco sabedoria humana em vez de Ti. Tu és maior que Salomão, mais rico que o ouro, mais profundo que os mares. Que eu busque Teu conselho acima de tudo. Amém.', 'cor': '#ffd700'},
        {'dia': 27, 'titulo': 'Lázaro, Sai Fora!', 'passagem': 'João 11:1-44', 'texto': 'Lázaro morreu e estava na sepultura há quatro dias. Jesus chegou e disse: "Lázaro, sai fora!" E o morto saiu, ainda envolto nos panos mortuários.', 'reflexao': 'A ressurreição de Lázaro é prelúdio da ressurreição final. Jesus tem poder sobre a morte. "Eu sou a ressurreição e a vida" (Jo 11:25). Quem crê em Jesus, mesmo que morra, viverá. A morte não é a última palavra para o crente.', 'oracao': 'Ressuscitador de Lázaro, Tu tens poder sobre a morte e a vida. Quando as situações na minha vida parecem mortas e enterradas há dias, lembra-me que Tu podes dizer "sai fora" e trazer vida. Amém.', 'cor': '#ff6b35'},
        {'dia': 28, 'titulo': 'Nascido de Novo', 'passagem': 'João 3:1-21', 'texto': 'Nicodemo veio a Jesus de noite. Jesus disse: "Em verdade, em verdade te digo, que quem não nascer de cima não pode ver o reino de Deus." E "Deus amou o mundo de tal maneira que deu o Seu Filho unigênito."', 'reflexao': 'João 3:16 é o versículo mais conhecido da Bíblia, mas todo o diálogo com Nicodemo é rico: nascemos de novo pelo Espírito, assim como nascemos fisicamente. A cruz é o meio da salvação - seremos salvos quando "o Filho do homem for levantado" (crucificado).', 'oracao': 'Deus que amou o mundo, obrigado por dar Teu Filho por mim. Nasce em mim de novo pelo Teu Espírito. Que eu viva como nova criatura, não como escravo do pecado, mas como filho livre de Deus. Amém.', 'cor': '#00ff88'},
        {'dia': 29, 'titulo': 'A Videira e os Ramos', 'passagem': 'João 15:1-11', 'texto': '"Eu sou a videira verdadeira, e Meu Pai é o lavrador. Todo ramo em mim que não dá fruto, Ele corta; e todo que dá fruto, poda para que produza mais fruto."', 'reflexao': 'A união com Cristo é essencial para a vida cristã. Sem Ele nada podemos fazer. O fruto da videira é o resultado da abertura em comunhão com Cristo. A poda é dolorosa mas necessária para maior frutificação. Perseverar na fé é fruto da verdadeira união com Cristo.', 'oracao': 'Videira divina, mantém-me unido a Ti. Quando me afastar, poda-me. Quando estiver seco, rega-me. Que eu produza frutos de amor, alegria e paz, somente porque estou enxertado em Ti. Amém.', 'cor': '#00ff88'},
        {'dia': 30, 'titulo': 'O Bom Pastor', 'passagem': 'João 10:1-18', 'texto': '"Eu sou o bom pastor. O bom pastor dá a sua vida pelas ovelhas. Eu conheço as Minhas ovelhas, e as Minhas me conhecem, assim como o Pai Me conhece e Eu conheço o Pai."', 'reflexao': 'Jesus é o Pastor que conhece cada ovelha por nome. Ele não foge do lobo como os mercenários. Deu Sua vida voluntariamente e tem poder para tomá-la de volta. Esta é a segurança eterna do crente: a mão do Pai e a mão do Filho guardam a ovelha.', 'oracao': 'Bom Pastor, obrigado por conheceres meu nome e cuidares de mim. Que eu ouça Tua voz e não siga vozes estranhas. Tu davas a Tua vida por mim; que eu viva para Ti todos os dias. Amém.', 'cor': '#00d4ff'},
        {'dia': 31, 'titulo': 'O Amor de Deus por Israel', 'passagem': 'Deuteronômio 7:7-9', 'texto': '"O Senhor vos elegeu e vos amou, não porque fôsseis mais numeroso que todos os povos, mas porque o Senhor vos amou e quis guardar o juramento que fizera a vossos pais."', 'reflexao': 'Deus não nos escolheu por méritos nossos, mas pela Sua graça soberana. Israel era o menor dos povos, mas Deus o amou. Assim também nos escolheu na graça, não pelas nossas obras. A eleição é tema central da teologia reformada e revela a soberania de Deus.', 'oracao': 'Deus de eleição, obrigado por me teres escolhido sem eu merecer. Tu me amaste antes que eu te amasse, me buscaste quando eu fugia. Que eu viva grato pela Tua graça soberana que me salvou. Amém.', 'cor': '#a855f7'},
    ],
    # ... (posso adicionar mais meses)
}

