def get_devocional_do_dia(data=None):
    """Retorna o devocional para uma data específica."""
    if data is None:
        data = date.today()

    # Usa o dia do ano como índice no ciclo anual
    dia_do_ano = data.timetuple().tm_yday
    idx = (dia_do_ano - 1) % len(PASSAGENS_ANUAIS)
    ref, titulo, desc = PASSAGENS_ANUAIS[idx]

    # Pega devocional detalhado se disponível (janeiro)
    mes_nome = ['janeiro','fevereiro','marco','abril','maio','junho',
                'julho','agosto','setembro','outubro','novembro','dezembro'][data.month - 1]
    dev_mensal = DEVOCIONAIS.get(mes_nome, [])
    dev_detalhado = None
    for d in dev_mensal:
        if d['dia'] == data.day:
            dev_detalhado = d
            break

    if dev_detalhado:
        return {
            'titulo': dev_detalhado['titulo'],
            'passagem': dev_detalhado['passagem'],
            'texto': dev_detalhado['texto'],
            'reflexao': dev_detalhado['reflexao'],
            'oracao': dev_detalhado['oracao'],
            'cor': dev_detalhado.get('cor', '#00d4ff'),
            'dia': data.day,
            'mes': mes_nome,
            'ano': data.year,
        }

    return {
        'titulo': titulo,
        'passagem': ref,
        'texto': '',
        'reflexao': desc,
        'oracao': f'Senhor, guia-me pela Tua Palavra hoje. Que a verdade de {ref} transforme minha vida. Em nome de Jesus, amém.',
        'cor': '#00d4ff',
        'dia': data.day,
        'mes': mes_nome,
        'ano': data.year,
    }


def get_passagem_para_estudo(referencia):
    """Busca uma passagem para estudo a partir de uma referência."""
    ref_lower = referencia.lower()
    for ref, titulo, desc in PASSAGENS_ANUAIS:
        if ref_lower in ref.lower() or ref.lower() in ref_lower:
            return {'referencia': ref, 'titulo': titulo, 'descricao': desc}
    return None


def get_historico_devocional(usuario, dias=7):
    """Retorna devocionais dos últimos N dias para um usuário."""
    resultado = []
    for i in range(dias):
        data = date.today() - timedelta(days=i)
        dev = get_devocional_do_dia(data)
        dev['data'] = data.strftime('%d/%m/%Y')
        dev['lido'] = False  # Pode ser conectado ao banco de dados depois
        resultado.append(dev)
    return resultado
